/*selectBuyerMpSoGuessTempCarTechCostCenterPopList*/
SELECT KEP.F_SPLIT(TEXT2, '@@', 1) AS CLASS , TEXT1 AS COSTCENTER , KEP.F_SPLIT(TEXT2, '@@', 2) AS DISCRIPTION , KEP.F_SPLIT(TEXT4, '@@', 1) AS MODEL , KEP.F_SPLIT(TEXT3, '@@', 1) AS RSM , KEP.F_SPLIT(TEXT3, '@@', 2) AS SAP , KEP.F_SPLIT(TEXT4, '@@', 2) AS PNAME , CODE --[0] ,TEXT1 --[1] ,TEXT2 --[2] ,TEXT3 --[3] ,TEXT4 --[4] ,VALUE1 --[5] ,FLAG --[6] FROM ICOMCOD2 WHERE TYPE = #{st_type} AND COMPANY_CODE =#{st_buyer}
AND TEXT1 = #{st_code}
AND TEXT2 LIKE '%'||#{st_desc}||'%'
AND TEXT4 LIKE '%'||#{st_name}||'%'
